@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Emerald Analytics — dark forest-emerald data dashboard.
 *
 * Built from a single reference: a dark analytics dashboard with deep
 * forest-green / charcoal surfaces, a vivid emerald accent, data cards,
 * charts and a clean grotesque sans. The material language:
 *   - Deep forest-green canvas (the outer plane is almost emerald-black) with
 *     a faint top-down sheen, like a dark room lit from above.
 *   - Raised surfaces are flat charcoal-green panels separated by a soft
 *     hairline border, not heavy bevels: depth comes from a quiet ambient
 *     drop shadow plus a 0.0625rem top rim, never a four-sided folder rim.
 *   - One signature hue: vivid emerald, carried by the primary CTA, filled
 *     controls, focus ring, links and the chart ramp.
 *   - Glow lives only on the emerald primary (a soft emerald halo); every
 *     other shadow is a clean neutral-green black ambient.
 *
 * Per repo rule every colour is oklch(), including inside shadow stacks.
 */

:root {
  /* ─── Surfaces: elevation = lighter charcoal-green panels ─── */
  --background: oklch(0.17 0.022 162);        /* deep forest canvas */
  --foreground: oklch(0.97 0.005 160);        /* near-white, faint green cast */

  --card: oklch(0.215 0.022 164);             /* raised data panel */
  --card-foreground: oklch(0.97 0.005 160);

  --popover: oklch(0.235 0.023 164);          /* floating surface */
  --popover-foreground: oklch(0.97 0.005 160);

  /* ─── Primary: vivid emerald (the lone hue) ─── */
  --primary: oklch(0.72 0.17 158);
  --primary-foreground: oklch(0.16 0.03 160);

  --secondary: oklch(0.26 0.024 164);
  --secondary-foreground: oklch(0.93 0.008 160);

  --muted: oklch(0.235 0.02 164);
  --muted-foreground: oklch(0.68 0.018 160);

  --accent: oklch(0.3 0.035 160);             /* emerald-tinted hover surface */
  --accent-foreground: oklch(0.97 0.005 160);

  --destructive: oklch(0.6 0.2 22);
  --destructive-foreground: oklch(0.98 0 0);

  --border: oklch(1 0 0 / 0.08);
  --input: oklch(1 0 0 / 0.045);
  --ring: oklch(0.72 0.17 158);
  --radius: 0.625rem;                          /* 0.625rem: clean medium card radius */

  /*
   * ─── Shadow scale ───
   * Flat-clean depth: a single faint top rim over a quiet neutral-green black
   * ambient pool that throws farther at higher tiers. No side rims, no bevel,
   * matching the dashboard's calm panel separation.
   */
  --shadow-xs:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.04),
    0 0.0625rem 0.125rem oklch(0.12 0.02 162 / 0.5);

  --shadow-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.05),
    0 0.0625rem 0.125rem oklch(0.12 0.02 162 / 0.5),
    0 0.25rem 0.75rem -0.1875rem oklch(0.1 0.02 162 / 0.45);

  --shadow-md:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.06),
    0 0.125rem 0.25rem oklch(0.1 0.02 162 / 0.5),
    0 0.625rem 1.5rem -0.375rem oklch(0.08 0.015 162 / 0.5);

  --shadow-lg:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 1rem 2.5rem -0.625rem oklch(0.07 0.015 162 / 0.6),
    0 1.5625rem 3.125rem -0.875rem oklch(0.06 0.012 162 / 0.5);

  --shadow-xl:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.08),
    0 1.5rem 3.5rem -0.75rem oklch(0.06 0.012 162 / 0.65),
    0 2.5rem 5rem -1.375rem oklch(0.05 0.01 162 / 0.55);

  /* Aliases used directly by component class strings ([box-shadow:var(--shadow-s)] etc). */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);

  /* Inset/pressed — inputs sit slightly recessed below the panel. */
  --shadow-inset:
    inset 0 0.0625rem 0.125rem oklch(0.1 0.02 162 / 0.45),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.03);

  /* Default raised control. */
  --shadow-button:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 0.0625rem 0.125rem oklch(0.1 0.02 162 / 0.5),
    0 0.25rem 0.625rem -0.1875rem oklch(0.08 0.015 162 / 0.45);

  --shadow-button-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.09),
    0 0.125rem 0.25rem oklch(0.1 0.02 162 / 0.55),
    0 0.5rem 1.125rem -0.25rem oklch(0.08 0.015 162 / 0.5);

  /* Emerald primary fill — flat emerald lit from above with a soft emerald halo.
     Soft layered falloff (no hard ring, large blur, low alpha) so the glow fades
     smoothly on the near-black ground instead of banding. */
  --shadow-primary:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.28),
    inset 0 -0.0625rem 0.0625rem oklch(0.1 0.02 162 / 0.32),
    0 0.0625rem 0.125rem oklch(0.1 0.02 162 / 0.55),
    0 0.1875rem 0.5rem -0.125rem oklch(0.1 0.02 162 / 0.45),
    0 0.5625rem 1.375rem -0.375rem oklch(0.72 0.17 158 / 0.3);

  /* Surface sheens reused by raised panels / bright slots (no texture, clean). */
  --emerald-sheen: linear-gradient(oklch(0.235 0.024 164) 0%, oklch(0.205 0.021 163) 100%);
  --emerald-bright: linear-gradient(oklch(0.78 0.16 158) 0%, oklch(0.7 0.17 158) 100%);

  /* ─── Chart palette: emerald ramp (one hue, five shades). ─── */
  --chart-1: var(--primary);
  --chart-2: oklch(from var(--primary) calc(l - 0.08) calc(c * 0.95) h);
  --chart-3: oklch(from var(--primary) calc(l - 0.16) calc(c * 0.88) h);
  --chart-4: oklch(from var(--primary) calc(l - 0.24) calc(c * 0.8) h);
  --chart-5: oklch(from var(--primary) calc(l - 0.32) calc(c * 0.72) h);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.375rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-inter), "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: compact;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 46);
  --layout-inset: calc(var(--spacing, 0.25rem) * 4);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 6);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 3);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 4);
}

